<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Number Battle</title><style>body{margin:0;background:#070b18;color:#f5f7ff;font:16px Arial;min-height:100vh;display:grid;place-items:center}.box{width:min(620px,90vw);background:#111a31;border:1px solid #ffffff25;border-radius:18px;padding:28px;box-shadow:0 15px 60px #0008}h1{color:#82f2d3}input,button{padding:12px;border-radius:8px;border:0;margin:5px;font-size:16px}input{background:#ffffff15;color:#fff}button{background:#80efd0;color:#07101d;font-weight:bold;cursor:pointer}.hidden{display:none}.row{padding:10px;border-bottom:1px solid #ffffff1c}.muted{color:#a6b2d6}#messages{height:180px;overflow:auto;background:#0003;padding:8px;border-radius:8px}small{color:#ffb0bf}</style></head><body><main class="box"><h1>◇ Number Battle</h1><section id="auth"><p class="muted">Four digits. One winner.</p><input id="username" placeholder="Username"><input id="email" placeholder="Email"><input id="password" type="password" placeholder="Password"><button onclick="auth('register')">Sign up</button><button onclick="auth('login')">Login</button><small id="authError"></small></section><section id="lobby" class="hidden"><p>Welcome, <b id="name"></b>!</p><button onclick="createRoom()">Create room</button><input id="code" maxlength="6" placeholder="ROOM CODE"><button onclick="joinRoom()">Join room</button></section><section id="game" class="hidden"><p>Room <b id="roomCode"></b> · <span id="status"></span></p><div id="players" class="row"></div><div id="setup"><input id="secret" maxlength="4" inputmode="numeric" placeholder="Your secret"><button onclick="ready()">Lock & ready</button></div><div id="play" class="hidden"><input id="guess" maxlength="4" inputmode="numeric" placeholder="Your guess"><button onclick="guess()">Guess</button><div id="history"></div></div><h3>Chat</h3><div id="messages"></div><input id="message" maxlength="500" placeholder="Message"><button onclick="chat()">Send</button><small id="error"></small></section></main><script>let room='';const call=async(a,b={})=>{let r=await fetch('api.php?action='+a,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),raw=await r.text(),j;try{j=JSON.parse(raw)}catch{throw Error('Server API did not respond. Re-upload api.php and check config.php. (HTTP '+r.status+')')}if(j.error)throw Error(j.error);return j};const fail=e=>document.querySelector('#error').textContent=e.message;async function auth(a){try{let x=await call(a,{username:username.value,email:email.value,password:password.value});name.textContent=x.user.username;auth.classList.add('hidden');lobby.classList.remove('hidden')}catch(e){authError.textContent=e.message}}async function createRoom(){let x=await call('create');room=x.code;open()}async function joinRoom(){try{room=code.value.toUpperCase();await call('join',{code:room});open()}catch(e){fail(e)}}function open(){lobby.classList.add('hidden');game.classList.remove('hidden');roomCode.textContent=room;state();setInterval(state,2000)}async function ready(){try{await call('ready',{code:room,secret:secret.value});state()}catch(e){fail(e)}}async function guess(){try{await call('guess',{code:room,guess:guess.value});guess.value='';state()}catch(e){fail(e)}}async function chat(){try{await call('chat',{code:room,text:message.value});message.value='';state()}catch(e){fail(e)}}async function state(){try{let x=await call('state',{code:room});status.textContent=x.room.status+(x.room.status==='finished'?' — Winner: '+x.room.winner_name:'');players.textContent=x.players.map(p=>p.username+(p.ready?' ✓':' ⏳')).join('  |  ');setup.classList.toggle('hidden',x.room.status!=='waiting');play.classList.toggle('hidden',x.room.status!=='playing');history.innerHTML=x.guesses.map(g=>'<div class="row"><b>'+g.username+'</b> guessed '+g.value+' — digits '+g.correct_digits+', positions '+g.correct_positions+'</div>').join('');messages.innerHTML=x.messages.map(m=>'<p><b>'+m.username+':</b> '+m.text.replace(/</g,'&lt;')+'</p>').join('')}catch(e){fail(e)}}</script></body></html>
